changeSet.rollback:
if Not exists (select * from [INFORMATION_SCHEMA].[ROUTINES] where SPECIFIC_SCHEMA = 'integration' and SPECIFIC_NAME = 'GetObjectByAssetTypeId') begin EXEC('CREATE FUNCTION [integration].[GetObjectByAssetTypeId] ( @id int ) RETURNS varchar(50) AS BEGIN DECLARE @o varchar(50)
SELECT @o = [Object] from AssetType where ID = @id
RETURN @o END') end
